"""Fixed Blender subprocess entry. Input paths are generated by the private service."""
import json
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[2]))
from src.refine_v4.runner import execute, save, sha


def main():
    request_path = Path(sys.argv[sys.argv.index("--") + 1]).resolve(strict=True)
    request = json.loads(request_path.read_text())
    folder = request_path.parent / "result"
    receipt = execute(request, request_path.parent, folder)
    receipt["after_sha256"] = sha(folder / "after.fbx")
    save(folder / "receipt.json", receipt)


if __name__ == "__main__":
    main()
